    const grab = k => [...root.querySelectorAll('span, div')].filter(e => e.children.length === 0 && e.textContent.trim() === k).map(e => e.nextElementSibling && e.nextElementSibling.textContent.trim()).filter(Boolean);
    const apa = grab('APA'), interp = grab('INTERPRETATION');
    const keyOf = el => Object.keys(this._svgs || {}).find(k => this._svgs[k] === el);
    const imgs = [];
    for (const svg of [...root.querySelectorAll('svg[viewBox]')].filter(s => s.getBoundingClientRect().width > 250)) {
      try {
        const vb = svg.viewBox.baseVal, xml = new XMLSerializer().serializeToString(svg);
        const img = new Image(); await new Promise((ok, no) => { img.onload = ok; img.onerror = no; img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(xml); });
        const c = document.createElement('canvas'); c.width = vb.width * 2; c.height = vb.height * 2;
        const ctx = c.getContext('2d'); ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, c.width, c.height); ctx.drawImage(img, 0, 0, c.width, c.height);
        const k = keyOf(svg);
        imgs.push({ src: c.toDataURL('image/png'), svg: this.svgExport(svg), w: Math.min(620, vb.width), h: vb.height, title: k ? this.plotTitle(k, (this._plotName || {})[k]) : '' });
      } catch (e) {}
    }
