    if (cmd) B.push({ k: 'p', t: [{ t: 'Command: ', b: true }, { t: (S.dialect === 'stata' ? '. ' : '> ') + cmd.replace(/\n/g, '  '), mono: true }] });
    if (key) B.push({ k: 'p', t: [{ t: 'Key result: ', b: true }, key.text] });
    if (g) B.push({ k: 'table', title: g.title, head: g.head, rows: g.rows, note: [g.note, stamp + '.'].filter(Boolean).join(' ') });
    else if (tbl) B.push({ k: 'pre', t: tbl });
    if (d && d.t === 'reg') { try { const vr = [...root.querySelectorAll('[data-screen-label="VIF"] div[title]')].map(e => { const r = e.parentElement.children; return [e.textContent.trim(), r[1].textContent.trim(), r[2].textContent.trim()]; }); if (vr.length) B.push({ k: 'table', title: 'Variance inflation factors', head: [['Variable', 'VIF', '1/VIF']], rows: vr, note: 'Stata: estat vif. ' + stamp + '.' }); } catch (e) {} }
    apa.forEach(t => B.push({ k: 'p', t: [{ t: 'APA: ', b: true }, { t, i: true }] }));
    interp.forEach(t => B.push({ k: 'p', t }));
    imgs.forEach(im => B.push({ k: 'img', src: im.src, svg: im.svg, w: im.w, h: im.h, title: im.title }));
    const html = '<div style="font-family: Calibri, Arial, sans-serif; font-size: 11pt;"><h3 style="margin: 0 0 4pt;">' + esc(lab) + ' — ' + esc(S.fileName) + '</h3>' + this.blocksHTML(B, null) + '</div>';
    const txt = [lab + ' — ' + S.fileName, stamp, cmd ? '. ' + cmd : '', key ? 'Key result: ' + key.text : '', tbl, ...apa.map(t => 'APA: ' + t), ...interp].filter(Boolean).join('\n\n');
