  asCompute(packet,token){
    const inline=()=>new Promise((resolve,reject)=>setTimeout(()=>{try{resolve(this._E.gmRun(packet));}catch(e){reject(e);}},20));
    if(this._asWorker===undefined){try{const url=URL.createObjectURL(new Blob([this._E.gmEngineSource()],{type:'text/javascript'}));this._asWorker=new Worker(url);URL.revokeObjectURL(url);}catch(e){this._asWorker=null;}}
    const w=this._asWorker;if(!w)return inline();
    return new Promise((resolve,reject)=>{
      const done=()=>{w.removeEventListener('message',onMsg);w.removeEventListener('error',onErr);this._asPending=null;};
      const onMsg=e=>{if(e.data?.token!==token)return;done();resolve(e.data.result);};
      const onErr=e=>{done();try{w.terminate();}catch(_){}this._asWorker=null;e.preventDefault?.();inline().then(resolve,reject);};
      w.addEventListener('message',onMsg);w.addEventListener('error',onErr);this._asPending={reject,done};
      try{w.postMessage({token,packet});}catch(e){done();inline().then(resolve,reject);}
    });
  }
  // Summary-statistics inputs: plain labels and checks before R starts, naming the field to fix.
  asFieldLabel(id,k){
    const two=id==='summary_t2'||id==='prop2';
    const L={mean1:two?'Mean, group 1':'Mean',sd1:two?'Standard deviation, group 1':'Standard deviation',n1:two?'Sample size (N), group 1':'Sample size (N)',mean2:'Mean, group 2',sd2:'Standard deviation, group 2',n2:'Sample size (N), group 2',meanDifference:'Mean of the differences',sdDifference:'Standard deviation of the differences',pairs:'Number of pairs',successes:'Number of successes',trials:'Number of trials (N)',successes1:'Successes, group 1',trials1:'Trials (N), group 1',successes2:'Successes, group 2',trials2:'Trials (N), group 2',counts:'Observed counts (comma-separated)',expected:'Expected proportions (comma-separated; blank = equal)',table:'2 × 2 table counts (a, b, c, d)'};
    if(k==='null')return id==='summary_t1'?'Hypothesized mean (H0)':id==='summary_tp'?'Hypothesized mean difference (H0)':['prop1','binomial'].includes(id)?'Hypothesized proportion (H0, between 0 and 1)':'';
    return L[k]||'';
  }
  asSummaryCheck(info,c){
    const summary=info.id.startsWith('summary_t')||c.inputMode==='summary';if(!summary)return '';
    const val=k=>{const v=c.options?.[k]??info.options[k];return v===''||v==null?NaN:Number(v);},name=k=>'“'+(this.asFieldLabel(info.id,k)||k)+'”';
    for(const k of info.summary){
      if(['counts','expected','table'].includes(k)){const raw=String(c.options?.[k]??info.options[k]??'').trim();if(k==='expected'&&!raw)continue;const xs=raw.split(/[\s,;]+/).filter(Boolean).map(Number);if(!xs.length||xs.some(x=>!Number.isFinite(x)||x<0))return 'Enter '+name(k)+' as non-negative numbers separated by commas.';if(k==='table'&&xs.length!==4)return 'Enter the four cells of the 2 × 2 table: a, b, c, d.';continue;}
      const v=val(k);if(!Number.isFinite(v))return 'Enter a number for '+name(k)+'.';
      if(/^sd/.test(k)&&!(v>0))return name(k)+' must be greater than 0.';
      if(/^n\d$|^pairs$/.test(k)&&!(Number.isInteger(v)&&v>=2))return name(k)+' must be a whole number of at least 2.';
      if(/^trials/.test(k)&&!(Number.isInteger(v)&&v>=1))return name(k)+' must be a whole number of at least 1.';
      if(/^successes/.test(k)){const t=val(k.replace('successes','trials'));if(!(Number.isInteger(v)&&v>=0))return name(k)+' must be a whole number (0 or more).';if(Number.isFinite(t)&&v>t)return name(k)+' cannot exceed the number of trials.';}
      if(k==='null'&&['prop1','binomial'].includes(info.id)&&!(v>0&&v<1))return name(k)+' must be between 0 and 1.';
    }
    return '';
  }
  // Run feedback sits under the Run button, where the user is looking, and scrolls into view.
