      cloud: { split: '', view: 'each', gN: 4, gPick: [], same: true, colorBy: 'bands', basis: 'count', bands: null, one: '#2E7D58', max: 80, rotate: 0, shape: 'ellipse', font: 'Hanken Grotesk', seed: 1234 },
