    const sig = FT.sig + '|' + CU.what + '|' + labels.join('¦').length + '|' + labels.length + '|' + CU.weight + '|' + dist + '|' + CU.link + '|' + T.by + CU.byYear + CU.nWords + CU.nTexts;
