    t += '<tr>' + td('', 'left', 'border-top:1.5pt solid #000;') + T.head.map(hd => td(hd.num, 'center', 'border-top:1.5pt solid #000;')).join('') + '</tr>';
    t += '<tr>' + td('', 'left') + T.head.map(hd => td(esc(hd.dep), 'center', 'font-style:italic;')).join('') + '</tr>';
