    L.push(' & ' + T.head.map(hd => hd.num).join(' & ') + ' \\\\');
    L.push(' & ' + T.head.map(hd => e(hd.dep)).join(' & ') + ' \\\\');
    L.push(' & ' + T.head.map(hd => e(hd.kind)).join(' & ') + ' \\\\', '\\midrule');
