      {
        const chipI = on => "font-family: var(--fMono, 'Space Mono', monospace); font-size: 11px; border-radius: 999px; padding: 4px 11px; cursor: pointer; white-space: nowrap; " + (on ? 'color: var(--cFFFFFF, #FFFFFF); background: var(--c1F6447, #1F6447); border: 1px solid var(--c143E2D, #143E2D);' : 'color: var(--c2B271E, #2B271E); background: var(--cFFFFFF, #FFFFFF); border: 1px solid var(--cD2C5AF, #D2C5AF);');
        const ixL = this.ixValid();
        out.ixShow = S.predictors.length >= 2;
        out.ixHasRows = ixL.length > 0;
        out.ixRows = ixL.map(([a1, b1]) => ({ label: a1 + ' \u00d7 ' + b1, remove: () => this.setState(s => ({ regIx: (s.regIx || []).filter(p => !(p[0] === a1 && p[1] === b1)) })) }));
        out.ixABtns = S.predictors.map(p => ({ label: p, style: chipI(S.ixA === p), click: () => this.setState({ ixA: p, ixB: S.ixB === p ? '' : S.ixB }) }));
        out.ixBBtns = S.predictors.filter(p => p !== S.ixA).map(p => ({ label: p, style: chipI(S.ixB === p), click: () => this.setState({ ixB: p }) }));
        const canIx = !!(S.ixA && S.ixB && S.ixA !== S.ixB && S.predictors.includes(S.ixA) && S.predictors.includes(S.ixB));
        out.ixAddStyle = "font-family: var(--fUI, 'Hanken Grotesk', sans-serif); font-weight: 700; font-size: 11px; letter-spacing: 0.06em; border-radius: 9px; padding: 6px 12px; white-space: nowrap; " + (canIx ? 'cursor: pointer; color: var(--cFFFFFF, #FFFFFF); background: var(--cC4681E, #C4681E); border: 1px solid var(--cA3540F, #A3540F);' : 'cursor: default; color: var(--c6B6455, #6B6455); background: var(--cF4EEE3, #F4EEE3); border: 1px solid var(--cE3D8C4, #E3D8C4);');
        out.ixAdd = () => { if (!canIx) return; const isCat = p => !!(this.effMeta(p) && this.effMeta(p).treatAs === 'categorical'); const A = S.ixA, B = S.ixB; const num = !isCat(A) ? A : !isCat(B) ? B : A, cat = isCat(B) && B !== num ? B : isCat(A) && A !== num ? A : ''; this.setState(s => ({ regIx: [...(s.regIx || []), [A, B]], ixA: '', ixB: '', mgX: num, mgBy: cat })); };
      }
